from __future__ import annotations

import json
import threading
import zipfile
from concurrent.futures import ThreadPoolExecutor
from pathlib import Path
from typing import Annotated, Any

from fastapi import FastAPI, File, Form, HTTPException, UploadFile
from fastapi.responses import FileResponse, JSONResponse
from fastapi.staticfiles import StaticFiles

from palantum.export import export_project
from palantum.orchestrator import _schema, analyze, cut, gate
from palantum.state import load

ROLE_NAMES = {
    "A1": "Script Supervisor",
    "A2": "Director",
    "A3": "Stratege",
    "A4": "Cutter",
    "A7": "QC",
}
_EXECUTOR = ThreadPoolExecutor(max_workers=1)
_LOCK = threading.Lock()


def _sessions(edit_dir: Path) -> list[dict[str, Any]]:
    path = edit_dir / "sessions.json"
    raw: dict[str, Any] = {}
    if path.exists():
        try:
            loaded = json.loads(path.read_text())
            if isinstance(loaded, dict):
                raw = loaded
        except (OSError, TypeError, ValueError):
            pass
    return [
        {
            "role": ROLE_NAMES[role],
            "status": str(raw.get(role, {}).get("status", "idle")),
            "url": raw.get(role, {}).get("url"),
        }
        for role in ROLE_NAMES
    ]


def _note_payload(note: dict[str, Any], resolved: bool = False) -> dict[str, Any]:
    shot = note.get("shot")
    if not isinstance(shot, dict):
        shot = {"line": "", "framing": "", "duration_s": 0, "delivery": ""}
    return {
        "beat": str(note.get("beat", "")),
        "impact": str(note.get("impact", "medium")),
        "resolved": resolved,
        "why": str(note.get("why", "")),
        "shot": {
            "line": str(shot.get("line", "")),
            "framing": str(shot.get("framing", "")),
            "duration_s": shot.get("duration_s", 0),
            "delivery": str(shot.get("delivery", "")),
        },
    }


def state_payload(videos_dir: Path) -> dict[str, Any]:
    edit_dir = videos_dir / "edit"
    state = load(edit_dir, _schema())
    sources = state.get("meta", {}).get("sources", [])
    has_sources = bool(sources) or any(
        next(videos_dir.glob(pattern), None) is not None for pattern in ("*.mp4", "*.mov")
    )
    final = edit_dir / "final.mp4"
    if not has_sources:
        phase = "empty"
    elif final.exists():
        phase = "done"
    else:
        phase = "working"
    open_notes = [
        _note_payload(note) for note in state.get("director_notes", []) if isinstance(note, dict)
    ]
    resolved_notes = []
    for item in state.get("resolved_notes", []):
        if not isinstance(item, dict):
            continue
        nested = item.get("note")
        note = nested if isinstance(nested, dict) else item
        resolved_notes.append(_note_payload(note, resolved=True))
    beats = [
        {
            "id": str(beat["id"]),
            "status": str(beat["status"]),
            "reason": str(beat.get("reason", "")),
        }
        for beat in state.get("beats", [])
    ]
    return {
        "phase": phase,
        "coverage": {"score": state.get("coverage_score", 0.0), "beats": beats},
        "notes": open_notes + resolved_notes,
        "sessions": [] if phase == "empty" else _sessions(edit_dir),
        "video_url": "/api/video" if final.exists() else None,
        "export_url": "/api/export" if final.exists() else None,
    }


def _process_upload(videos_dir: Path, sources: list[Path], brief: str | None) -> None:
    with _LOCK:
        edit_dir = videos_dir / "edit"
        for source in sources:
            analyze(edit_dir, [source], brief=brief)
        state = load(edit_dir, _schema())
        allowed, _ = gate(state, _schema())
        if allowed:
            all_sources = sorted(videos_dir.glob("*.mp4")) + sorted(videos_dir.glob("*.mov"))
            cut(edit_dir, all_sources)


def create_app(videos_dir: Path | str = ".") -> FastAPI:
    root = Path(videos_dir).resolve()
    root.mkdir(parents=True, exist_ok=True)
    app = FastAPI(title="Palantum")

    @app.get("/api/state")
    def api_state() -> dict[str, Any]:
        return state_payload(root)

    @app.post("/api/upload")
    async def api_upload(
        files: Annotated[list[UploadFile] | None, File()] = None,
        bracket_files: Annotated[list[UploadFile] | None, File(alias="files[]")] = None,
        brief: Annotated[str | None, Form()] = None,
    ) -> JSONResponse:
        files = (files or []) + (bracket_files or [])
        if not files:
            return JSONResponse({"error": "at least one file is required"}, status_code=400)
        sources: list[Path] = []
        for upload in files:
            name = Path(upload.filename or "upload.mp4").name
            destination = root / name
            with destination.open("wb") as handle:
                while chunk := await upload.read(1024 * 1024):
                    handle.write(chunk)
            sources.append(destination)
            await upload.close()
        _EXECUTOR.submit(_process_upload, root, sources, brief)
        return JSONResponse({"accepted": [path.name for path in sources], "phase": "working"})

    @app.get("/api/video")
    def api_video() -> FileResponse:
        path = root / "edit" / "final.mp4"
        if not path.exists():
            raise HTTPException(status_code=404, detail="final video is not ready")
        return FileResponse(path, media_type="video/mp4")

    @app.get("/api/export")
    def api_export() -> FileResponse:
        package = export_project(root / "edit")
        archive = root / "edit" / f"{package.name}.zip"
        with zipfile.ZipFile(archive, "w", zipfile.ZIP_DEFLATED) as handle:
            for path in package.rglob("*"):
                if path.is_file():
                    handle.write(path, path.relative_to(package.parent))
        return FileResponse(archive, media_type="application/zip", filename=archive.name)

    static = Path(__file__).parent / "static"
    app.mount("/", StaticFiles(directory=static, html=True), name="static")
    return app

from __future__ import annotations

import argparse
import json
from pathlib import Path

from palantum.engine.videouse import doctor
from palantum.export import export_project
from palantum.orchestrator import _schema, analyze, cut, gate
from palantum.state import load

BEATS = ("HOOK", "PROBLEM", "SOLUTION", "DEMO", "TRACTION", "TEAM", "ASK")
ANSI_BOLD = "\033[1m"
ANSI_RESET = "\033[0m"


def _dots(state: dict[str, object]) -> str:
    raw_beats = state["beats"]
    if not isinstance(raw_beats, list):
        return " ".join("○" for _ in BEATS)
    beats = {str(item["id"]): str(item["status"]) for item in raw_beats if isinstance(item, dict)}
    return " ".join(
        {"covered": "●", "weak": "◐", "missing": "○"}[beats.get(beat, "missing")] for beat in BEATS
    )


def print_state(state: dict[str, object]) -> None:
    print(_dots(state))
    notes = state.get("director_notes", [])
    if not isinstance(notes, list):
        return
    for note in notes:
        if not isinstance(note, dict):
            continue
        shot = note.get("shot")
        if not isinstance(shot, dict):
            continue
        print(f"\n{note.get('beat')} · {note.get('impact')} · {note.get('why')}")
        print(f"{ANSI_BOLD}{shot.get('line')}{ANSI_RESET}")
        print(f"  {shot.get('framing')} · {shot.get('duration_s')}s · {shot.get('delivery')}")


def main() -> None:
    parser = argparse.ArgumentParser(prog="palantum")
    parser.add_argument("--videos-dir", type=Path, default=Path("."))
    commands = parser.add_subparsers(dest="command", required=True)
    ingest = commands.add_parser("ingest")
    ingest.add_argument("files", nargs="+", type=Path)
    ingest.add_argument("--template-source", type=Path)
    commands.add_parser("status")
    cut_command = commands.add_parser("cut")
    cut_command.add_argument("--template-source", type=Path)
    commands.add_parser("export")
    doctor_command = commands.add_parser("doctor")
    doctor_command.add_argument("--template-source", type=Path)
    doctor_command.add_argument("--json", action="store_true")
    serve = commands.add_parser("serve")
    serve.add_argument("--host", default="127.0.0.1")
    serve.add_argument("--port", default=8000, type=int)
    args = parser.parse_args()
    videos_dir = args.videos_dir.resolve()
    edit_dir = videos_dir / "edit"
    if args.command == "doctor":
        report = doctor(args.template_source)
        if args.json:
            print(json.dumps(report.as_dict(), indent=2, ensure_ascii=False))
        else:
            for check in report.checks:
                marker = "ok" if check.ok else ("FAIL" if check.required else "optional")
                suffix = f" - {check.detail}" if check.detail else ""
                print(f"[{marker}] {check.name}: {check.value}{suffix}")
        raise SystemExit(0 if report.ok else 1)
    schema = _schema()
    if args.command == "status":
        print_state(load(edit_dir, schema))
        return
    if args.command == "ingest":
        sources = [
            path.resolve() if path.is_absolute() else (videos_dir / path).resolve()
            for path in args.files
        ]
        known: list[Path] = []
        for source in sources:
            known.append(source)
            print(f"\nIngesting {source.name}")
            state = analyze(edit_dir, known, args.template_source)
            print_state(state)
        return
    if args.command == "export":
        package = export_project(edit_dir)
        print(package)
        return
    if args.command == "serve":
        import uvicorn

        from palantum.web import create_app

        uvicorn.run(create_app(videos_dir), host=args.host, port=args.port)
        return
    sources = sorted(videos_dir.glob("*.mp4")) + sorted(videos_dir.glob("*.mov"))
    state = load(edit_dir, schema)
    allowed, notes = gate(state, schema)
    if not allowed:
        print_state(state)
        raise SystemExit(2)
    edl, qc = cut(edit_dir, sources, args.template_source)
    print(f"Rendered {edit_dir / 'final.mp4'}")
    print(json.dumps(qc, indent=2, ensure_ascii=False))

