globalThis.logoCheckTab = await browser.tabs.new();
await logoCheckTab.goto("http://127.0.0.1:8001/");
await logoCheckTab.playwright.waitForLoadState({state:"domcontentloaded"});
var logoMetrics = await logoCheckTab.playwright.locator(".corner-logo").evaluate(el => {
  const logo = el.getBoundingClientRect();
  const controls = [...document.querySelectorAll("#toolbar button:not([hidden])")].map(item => {
    const rect = item.getBoundingClientRect();
    return {id:item.id,left:rect.left,right:rect.right,top:rect.top,bottom:rect.bottom};
  });
  const overlaps = controls.filter(rect => !(logo.right < rect.left || logo.left > rect.right || logo.bottom < rect.top || logo.top > rect.bottom)).map(rect => rect.id);
  return {visible:getComputedStyle(el).display !== "none",width:logo.width,height:logo.height,right:innerWidth-logo.right,bottom:innerHeight-logo.bottom,naturalWidth:el.naturalWidth,naturalHeight:el.naturalHeight,overlaps};
});
var logoErrors = await logoCheckTab.dev.logs({levels:["error"],limit:20});
nodeRepl.write(JSON.stringify({logoMetrics,logoErrors},null,2));

